-- ============================================================
-- MIGRACAO 7: Endereco estruturado + limpeza de placeholders
--
-- 1) BKP: cria a coluna 'bkp_endereco' e guarda o endereco ORIGINAL
--    de todos os clientes (nunca sobrescreve o que ja foi salvo).
--    Rollback possivel a qualquer momento:
--       UPDATE clientes SET endereco = bkp_endereco;
-- 2) LIMPEZA: cadastros que tinham o texto-generico repetido
--    ("RUA, S/N . - BAIRRO, JATAI - GO" e variacoes) nao possuem
--    endereco real -> endereco fica vazio (original em bkp_endereco).
-- 3) ESTRUTURACAO: ~1032 enderecos reais analisados como
--    seguros ganham logradouro/numero/complemento/bairro/cidade/uf e
--    o campo 'endereco' e reescrito no padrao do sistema.
--    Enderecos duvidosos NAO sao tocados.
--
-- COMO USAR: rode no Supabase SQL Editor (preferencialmente 1x).
-- ============================================================

-- ============================================================
-- PARTE 1 - Backup (coluna nova + snapshot do texto original)
-- ============================================================
ALTER TABLE public.clientes
    ADD COLUMN IF NOT EXISTS bkp_endereco text DEFAULT NULL;

UPDATE public.clientes
SET bkp_endereco = endereco
WHERE bkp_endereco IS NULL
  AND endereco IS NOT NULL
  AND endereco <> '';

