-- ============================================================
-- PARTE 4 - Relatorio de conferencia
-- ============================================================
SELECT
    count(*)                                                    AS total_clientes,
    count(bkp_endereco)                                         AS com_backup,
    count(*) FILTER (WHERE logradouro IS NOT NULL AND logradouro <> '') AS endereco_estruturado,
    count(*) FILTER (WHERE endereco IS NULL OR endereco = '')   AS endereco_vazio,
    count(*) FILTER (WHERE endereco ~* 'RUA|AVENIDA|ALAMEDA')   AS endereco_preenchido
FROM public.clientes;
